{
  "name": "opencode-kratos",
  "version": "0.1.1",
  "description": "Persistent kratos-memory integration for OpenCode — context injection, per-prompt recall, auto-capture, session summaries",
  "type": "module",
  "license": "MIT",
  "main": ".opencode/plugins/kratos.js",
  "scripts": {
    "test": "node --test",
    "typecheck": "tsc --noEmit",
    "e2e": "node e2e/run.mjs"
  },
  "engines": {
    "node": ">=22.18.0"
  },
  "files": [
    "src",
    ".opencode"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "kratos",
    "memory",
    "ai-agents"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/MisterAssm/opencode-kratos.git"
  },
  "dependencies": {
    "@opencode/plugin": "^2.1.2"
  },
  "devDependencies": {
    "@types/node": "^24.0.0",
    "typescript": "^5.9.0"
  }
}
